// Node: "Guard 1: Size sanity"
// Place: AFTER all ffmpegCommandExecute nodes (they all converge here).
// Output 1 â†’ Pass (continue to duration check)
// Output 2 â†’ Fail (dead-end, source NOT replaced)
// Purpose: Reject encodes that didn't shrink the file meaningfully, OR
//          produced suspiciously small output (likely corrupt).

module.exports = async (args) => {
  const snap = (args.variables && args.variables.user) || {};
  const inputBytes = snap.sourceSize;
  const outputBytes = args.inputFileObj.file_size;

  if (!inputBytes) {
    args.jobLog('Size check: no source snapshot found â€” FAIL (will not replace)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  const ratio = outputBytes / inputBytes;
  args.jobLog(
    `Size check: ${(inputBytes / 1024).toFixed(2)}GiB â†’ ` +
      `${(outputBytes / 1024).toFixed(2)}GiB (${(ratio * 100).toFixed(1)}%)`,
  );

  if (outputBytes < inputBytes * 0.05) {
    args.jobLog('Size check: FAIL â€” output suspiciously small (<5% of source), likely corrupt');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  if (ratio >= 0.95) {
    args.jobLog('Size check: FAIL â€” output not meaningfully smaller (>=95% of source)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

// Node: "Guard 2: Duration integrity"
// Place: AFTER size check.
// Output 1 â†’ Pass
// Output 2 â†’ Fail (truncated or corrupt output)
// Purpose: Catches encodes that crashed mid-way and produced a truncated file.
//          Allows up to 0.5% duration drift (rounding/container differences).

module.exports = async (args) => {
  const snap = (args.variables && args.variables.user) || {};
  const inDur = snap.sourceDuration;

  const fmt = (args.inputFileObj.ffProbeData || {}).format || {};
  const outDur = parseFloat(fmt.duration || 0);

  if (!inDur) {
    args.jobLog('Duration check: no source snapshot â€” PASS (skipping)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 1,
      variables: args.variables,
    };
  }

  if (!outDur) {
    args.jobLog('Duration check: cannot read output duration â€” FAIL');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  const ratio = outDur / inDur;
  args.jobLog(
    `Duration check: ${inDur.toFixed(1)}s â†’ ${outDur.toFixed(1)}s (${(ratio * 100).toFixed(2)}%)`,
  );

  if (ratio < 0.995 || ratio > 1.005) {
    args.jobLog('Duration check: FAIL â€” duration drift > 0.5%');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

// Node: "Guard 3: HDR metadata survived"
// Place: AFTER duration check, BEFORE rename.
// Output 1 â†’ Pass (continue to rename â†’ replace)
// Output 2 â†’ Fail (HDR side data was lost in encode, source NOT replaced)
// Purpose: Ensures mastering display + content light level survived the QSV pipeline.
//          SDR sources pass through automatically (no HDR to check).

module.exports = async (args) => {
  const snap = (args.variables && args.variables.user) || {};

  if (!snap.sourceWasHDR) {
    args.jobLog('HDR survival: source was SDR â€” PASS (no HDR check needed)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 1,
      variables: args.variables,
    };
  }

  // First check stream-level side data (fast, already in ffProbeData)
  const streams = (args.inputFileObj.ffProbeData || {}).streams || [];
  const videoStream = streams.find((s) => s.codec_type === 'video') || {};
  const streamSd = videoStream.side_data_list || [];

  let hasMaster = streamSd.some((x) =>
    (x.side_data_type || '').toLowerCase().includes('mastering'),
  );
  let hasCLL = streamSd.some((x) =>
    (x.side_data_type || '').toLowerCase().includes('content light'),
  );

  // Fall back to frame-level probe if stream-level didn't have it
  if (!hasMaster || !hasCLL) {
    try {
      const { execSync } = require('child_process');
      const out = execSync(
        `ffprobe -v error -select_streams v:0 -read_intervals "%+#1" ` +
          `-show_frames -show_entries frame=side_data_list -of json ` +
          `"${args.inputFileObj._id}"`,
        { maxBuffer: 10 * 1024 * 1024 },
      ).toString();
      const frameSd = ((JSON.parse(out).frames || [])[0] || {}).side_data_list || [];
      hasMaster =
        hasMaster ||
        frameSd.some((x) => (x.side_data_type || '').toLowerCase().includes('mastering'));
      hasCLL =
        hasCLL ||
        frameSd.some((x) => (x.side_data_type || '').toLowerCase().includes('content light'));
    } catch (e) {
      args.jobLog(`HDR survival: frame-level ffprobe failed (${e.message})`);
    }
  }

  args.jobLog(`HDR survival: mastering=${hasMaster} cll=${hasCLL}`);

  if (!hasMaster || !hasCLL) {
    args.jobLog('HDR survival: FAIL â€” HDR side data missing from output');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

